using System.ComponentModel.DataAnnotations; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore; using OrcaFacil.Domain.Entities; using OrcaFacil.Persistence; namespace OrcaFacil.Web.Areas.Admin.Pages.ReleaseNotes; [Authorize(Policy="SuperAdmin")] public sealed class IndexModel(OrcaFacilDbContext db):PageModel {public IReadOnlyList<ReleaseNote> Items{get;private set;}=[];[BindProperty,Required,StringLength(30)]public string Version{get;set;}="";[BindProperty,Required,StringLength(180)]public string Title{get;set;}="";[BindProperty,Required,StringLength(5000)]public string Description{get;set;}="";[BindProperty,Required,RegularExpression("Novidade|Melhoria|Correção|Segurança|Operação")]public string Category{get;set;}="Melhoria";[BindProperty]public DateTime ReleasedAt{get;set;}=DateTime.Today;[BindProperty]public bool IsPublished{get;set;} public async Task OnGetAsync(CancellationToken ct)=>await Load(ct);public async Task<IActionResult> OnPostAsync(CancellationToken ct){if(!ModelState.IsValid){await Load(ct);return Page();}db.ReleaseNotes.Add(new(){Version=Version.Trim(),Title=Title.Trim(),Description=Description.Trim(),Category=Category,ReleasedAt=DateTime.SpecifyKind(ReleasedAt,DateTimeKind.Utc),IsPublished=IsPublished});await db.SaveChangesAsync(ct);return RedirectToPage();}async Task Load(CancellationToken ct)=>Items=await db.ReleaseNotes.AsNoTracking().Where(x=>!x.IsDeleted).OrderByDescending(x=>x.ReleasedAt).ToListAsync(ct);}
